// precos.ts
export function comIva(valor, taxa) {     // noImplicitAny: TS7006 em valor e em taxa
  return valor * (1 + taxa);
}
export function procurar(lista, id) {     // noImplicitAny: TS7006 em lista e em id
  return lista.find((p) => p.id === id);  // noImplicitAny: TS7006 em p
}

