// Tipos de domínio: numa pasta própria (por exemplo src/dominio), importados pelo resto
export interface LinhaEncomenda {
  produto: string;
  quantidade: number;
  precoUnitario: number;
}

export interface Encomenda {
  id: string;
  linhas: LinhaEncomenda[];
  cupao?: string;
}

// Fronteira anotada (parâmetro e retorno); o interior fica com a inferência
export function totalEncomenda(encomenda: Encomenda): number {
  const subtotal = encomenda.linhas.reduce(
    (soma, linha) => soma + linha.quantidade * linha.precoUnitario,
    0,
  );
  const desconto = encomenda.cupao === "VERAO10" ? 0.1 : 0;
  return Math.round(subtotal * (1 - desconto) * 100) / 100;
}

// TODO(migracao): any temporário; tipar quando o módulo de relatórios for migrado
export function paraRelatorio(dados: any): string {
  return JSON.stringify(dados);
}

const encomenda: Encomenda = {
  id: "E1",
  linhas: [
    { produto: "Caneta", quantidade: 3, precoUnitario: 1.5 },
    { produto: "Caderno", quantidade: 2, precoUnitario: 4 },
  ],
  cupao: "VERAO10",
};

console.log(totalEncomenda(encomenda)); // 11.25
console.log(paraRelatorio({ id: encomenda.id, total: totalEncomenda(encomenda) })); // {"id":"E1","total":11.25}

