interface Item {
  nome: string;
  preco: number;
  qtd: number;
}

export function adicionar(carrinho: Item[], item: Item): Item[] {
  return [...carrinho, item];
}

export function total(carrinho: Item[]): number {
  return carrinho.reduce((soma, item) => soma + item.preco * item.qtd, 0);
}

let carrinho = adicionar([], { nome: "Livro", preco: 12, qtd: 1 });
carrinho = adicionar(carrinho, { nome: "Marcador", preco: 0.5, qtd: 4 });
console.log(total(carrinho)); // 14

// @ts-expect-error
adicionar(carrinho, { nome: "Caneta", preco: "1", qtd: 1 });

// conversor.js
// @ts-check
/**
 * @param {number} celsius
 * @returns {number}
 */
export function paraFahrenheit(celsius) {
  return celsius * 9 / 5 + 32;
}

// main.js
// @ts-check
import { paraFahrenheit } from "./conversor.js";

const valorDoFormulario = "20";
console.log(paraFahrenheit(valorDoFormulario));         // TS2345: Argument of type 'string' is not assignable to parameter of type 'number'.
console.log(paraFahrenheit(Number(valorDoFormulario))); // correto: 68

