/**
 * @param {Produto[]} lista
 * @param {string} codigo
 * @returns {Produto | undefined}
 */
export function procurar(lista, codigo) {
  return lista.find((p) => p.codigo === codigo);
}

const p = procurar(catalogo, "A1");
console.log(p.preco); // TS18048: 'p' is possibly 'undefined'.

interface Cliente {
  id: number;
  nome: string;
  email?: string;
}

export function procurarCliente(clientes: Cliente[], id: number): Cliente | undefined {
  return clientes.find((c) => c.id === id);
}

export function descrever(cliente: Cliente | undefined): string {
  if (cliente === undefined) {
    return "cliente inexistente";
  }
  const contacto = cliente.email ?? "sem email";
  return `${cliente.nome} (${contacto})`;
}

const clientes: Cliente[] = [
  { id: 1, nome: "Ana", email: "ana@exemplo.pt" },
  { id: 2, nome: "Rui" },
];

console.log(descrever(procurarCliente(clientes, 1))); // Ana (ana@exemplo.pt)
console.log(descrever(procurarCliente(clientes, 2))); // Rui (sem email)
console.log(descrever(procurarCliente(clientes, 9))); // cliente inexistente
